"""Stage 15A.3 scoped-participant artifacts."""
from __future__ import annotations
import json,statistics
from dataclasses import asdict
from pathlib import Path
from typing import Any
from .stage15a3 import participant_matrix,scoped_recommendation
def write(p:Path,v:Any)->None:p.parent.mkdir(parents=True,exist_ok=True);p.write_text(json.dumps(v,indent=2,sort_keys=True,default=lambda x:x.value)+"\n")
def svg(p:Path,title:str,lines:list[str])->None:p.parent.mkdir(parents=True,exist_ok=True);text=''.join(f'<text x="20" y="{55+i*28}" font-size="14">{x}</text>' for i,x in enumerate(lines));p.write_text(f'<svg xmlns="http://www.w3.org/2000/svg" width="950" height="{90+len(lines)*28}"><text x="20" y="25" font-size="20">{title}</text>{text}</svg>\n')
def generate(root:str|Path)->dict[str,Any]:
 root=Path(root);fresh=json.loads((root/'fresh_results.json').read_text());prior=json.loads(Path('evaluation_results/stage15a2/raw_results.json').read_text());matrix=participant_matrix();tool=fresh['tool']['successful_cycles'];rag=fresh['rag']['successful_cycles'];recommendation=scoped_recommendation(tool,rag);elig=fresh['eligibility_latency_ns'];performance={'eligibility_check_ns':{'median':statistics.median(elig),'p95':sorted(elig)[int(len(elig)*.95)-1]},'quiesce':'harness barrier; standalone latency not isolated','barrier_checkpoint_skew_ns':{'median':statistics.median(x['checkpoint_skew_ns'] for x in prior['multiservice'])},'fresh_reconnect':'included in per-cycle health oracle; standalone latency not isolated','health_check':'included in per-cycle health oracle; standalone latency not isolated'};multiservice={'status':'MULTI_SERVICE_RESTORE_SUPPORTED_SEQUENTIALLY','atomic_status':'ATOMIC_MULTI_SERVICE_SNAPSHOT_NOT_ESTABLISHED','cycles':'20/20','barrier_protocol':['stop new mutations','wait for in-flight operations','checkpoint participant A','checkpoint participant B','record checkpoint set','resume operations'],'median_skew_ns':statistics.median(x['checkpoint_skew_ns'] for x in prior['multiservice'])};second={'status':'SECOND_ENVIRONMENT_UNAVAILABLE','reason':'only Docker Desktop LinuxKit context available','paper_limitation':'Native CRIU checkpoint evidence remains limited to the privileged Docker Desktop LinuxKit environment.'};tree={**fresh['process_tree_reattempt'],'outcome':'PROCESS_TREE_NOT_SUPPORTED','supported_scope_fallback':'SINGLE_PROCESS'};socket={'persistent_client_survival':False,'fresh_reconnect_after_restore':True,'contract':['invalidate old connection','restore','health verification','fresh reconnect','verify state']};rejections=[x for x in matrix if not x['eligibility']['eligible']];contract={'mandatory':['one externally managed process','CRIU checkpoint and restore succeed','health check','structural state oracle','state digest oracle','fresh reconnect','mutation quiesce','observable restore failure'],'excluded':['filesystem transactional assumption','unmanaged external effects','persistent socket requirement','process trees','atomic multi-service groups'],'future_failure_status':['EXTERNAL_ROLLBACK_FAILED','PARTIAL_ROLLBACK_FAILURE']}
 sections={'participant_matrix/results.json':matrix,'single_process/results.json':{'tool':tool,'rag':rag,'tool_requested':20,'rag_requested':20},'second_environment/results.json':second,'process_tree/results.json':tree,'multiservice/results.json':multiservice,'sockets/results.json':socket,'filesystem/results.json':prior['boundary'],'observer/results.json':prior['boundary'],'eligibility/results.json':rejections,'performance/results.json':performance,'report/stage15b_recommendation.json':recommendation}
 for name,value in sections.items():write(root/name,value)
 tables=[matrix,rejections,{'tool':f'{tool}/20','rag':f'{rag}/20'},second,tree,multiservice,socket,[x['participant_id'] for x in rejections],contract,recommendation];names=['01_capabilities','02_eligibility','03_fresh_reliability','04_second_environment','05_process_tree','06_multiservice','07_sockets','08_rejected_categories','09_proposed_contract','10_recommendation']
 for n,v in zip(names,tables):write(root/'tables'/f'{n}.json',v)
 figures=[('01_scoped_model',['supported: single process','excluded: process tree / atomic group']),('02_eligibility_flow',['health + oracles + quiesce + reconnect','reject filesystem/effects/socket/tree/group']),('03_fresh_reliability',[f'tool {tool}/20',f'RAG {rag}/20']),('04_multiservice',['sequential barrier 20/20',f'median skew {multiservice["median_skew_ns"]/1e6:.2f} ms','atomicity not established']),('05_socket',['persistent survival: false','fresh reconnect: true']),('06_resources',['memory: supported','filesystem/effects: unsupported']),('07_process_tree',[tree['outcome']]),('08_lifecycle',['eligibility → quiesce → checkpoint → inference','reject → invalidate → restore → health → reconnect → digest'])]
 for i,(name,lines) in enumerate(figures,1):svg(root/'figures'/f'{i:02d}_{name}.svg',name.replace('_',' ').title(),lines)
 return {'recommendation':recommendation,'fresh':{'tool':tool,'rag':rag},'second':second,'tree':tree,'matrix':matrix,'performance':performance}
